      {actions.canEdit && <button className="button" type="button" disabled={busy} onClick={() => onAction('edit', item)}>Edit text</button>}
      {actions.canDelete && <button className="button danger" type="button" disabled={busy} onClick={() => onAction('delete', item)}>{actions.deleteScope === 'self' ? 'Remove from my view' : actions.deleteScope === 'unsend' ? 'Unsend message' : 'Delete message'}</button>}
